  ('الرمادي', 33.4258, 43.2990, 5, 'Al-Anbar'), ('الفلوجة', 33.3490, 43.7850, 4, 'Al-Anbar'), ('هيت', 33.6390, 42.8260, 3, 'Al-Anbar'), ('حديثة', 34.1380, 42.3760, 2, 'Al-Anbar'), ('الرطبة', 33.0300, 40.2830, 3, 'Al-Anbar'), ('عانة', 34.4690, 41.9610, 2, 'Al-Anbar'), ('القائم', 34.3770, 41.0160, 2, 'Al-Anbar'), ('الخالدية', 33.3700, 43.5800, 2, 'Al-Anbar'),
];

/// أهوار الجنوب (مستطيلات تقريبية): الوسطى، الحويزة، الحمّار
const _marshBoxes = <(double, double, double, double)>[
  (30.70, 31.20, 46.60, 47.30),
  (31.30, 31.90, 47.45, 47.95),
  (30.50, 30.85, 47.00, 47.60),
];

final Map<String, List<List<double>>> _govRings = {};

List<List<double>> _ringsOf(String k) => _govRings[k] ??= [
      for (final ring in (_govPoly[k] ?? '').split('|'))
        if (ring.isNotEmpty)
          [
            for (final p in ring.split(';'))
              for (final v in p.split(',')) double.parse(v),
          ],
    ];

bool _inRing(List<double> r, double lat, double lon) {
  var inside = false;
  final n = r.length ~/ 2;
  for (int i = 0, j = n - 1; i < n; j = i++) {
    final yi = r[i * 2], xi = r[i * 2 + 1], yj = r[j * 2], xj = r[j * 2 + 1];
    if ((yi > lat) != (yj > lat) && lon < (xj - xi) * (lat - yi) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}

double _kmBetween(double la1, double lo1, double la2, double lo2) {
  final dy = (la2 - la1) * 111.2, dx = (lo2 - lo1) * 111.2 * math.cos((la1 + la2) * math.pi / 360);
  return math.sqrt(dx * dx + dy * dy);
}

/// المحافظة والمكان ونوع المشهد من الإحداثيات فقط (بدون إنترنت). null إذا النقطة خارج العراق.
_Region? _offlineRegion(double lat, double lon) {
  if (lat < 28.9 || lat > 37.5 || lon < 38.7 || lon > 48.9) return null;
  // أقرب بلدة
  int bi = -1;
  double bd = 1e9;
  for (int i = 0; i < _towns.length; i++) {
    final t = _towns[i], d = _kmBetween(lat, lon, t.$2, t.$3);
    if (d < bd) {
      bd = d;
      bi = i;
    }
  }
  String? gov;
  for (final k in _govPoly.keys) {
    for (final r in _ringsOf(k)) {
      if (_inRing(r, lat, lon)) {
        gov = k;
        break;
      }
    }
    if (gov != null) break;
  }
  if (gov == null) {
    if (bd > 60) return null; // خارج العراق
    gov = _towns[bi].$5; // فجوة بسيطة على الحدود الداخلية
  }
  final t = _towns[bi];
  final urban = bd <= t.$4;
  final place = _govAr[gov] ?? gov;
  final sub = urban ? t.$1 : (bd <= 35 ? 'قرب ${t.$1}' : '');
  int biome = _bFarm;
  if (urban) {
    biome = _bCity;
  } else if (const ['Dohuk', 'Erbil', 'Al-Sulaimaniyah'].contains(gov)) {
    biome = _bMount;
  } else if (_marshBoxes.any((b) => lat >= b.$1 && lat <= b.$2 && lon >= b.$3 && lon <= b.$4)) {
    biome = _bMarsh;
  } else if (gov == 'Al-Anbar' && lon < 43.3 || gov == 'Al-Muthanna' && lon < 45.6 || gov == 'An-Najaf' && lon < 44.0 || gov == 'Karbala' && lon < 43.8 || gov == 'Ninawa' && lon < 41.9 || gov == 'Al-Basrah' && lon < 47.3 || gov == 'Dhi Qar' && lat < 30.9 && lon < 46.3) {
    biome = _bDesert;
  }
  return _Region(place, sub, biome, gov);
}
